int f_n_numofdigits(float n)
{
    //log10(x) = log(x) / log(10) = (1 / log(10)) * log(x)
    if(abs(n) == 0.){
        return 1;
    }
    if(abs(n) == 10.){
        return 2;
    }
    return int(floor((1. / log(10.)) * log(n) +1.));

} 
int f_n_digit(int number, int n_index) {  
    int n_numofdigits = f_n_numofdigits(float(number));
    n_index = (n_numofdigits-1) - n_index;
   return int((floor(float(number)/pow(10.0,float(n_index))))) % 10; 
} 

vec4 f_o_col_char(vec2 o_trn_fc_nor, vec2 o_char){

    vec2 o_scl_chars = vec2(16.);
    vec2 o = (o_trn_fc_nor.xy/o_scl_chars.xy)+vec2(1./16.)*o_char;
    vec4 o_col = texture(iChannel0, o);
    return o_col;
}
vec4 f_o_col_num(vec2 o_trn_fc_nor, int n){


    vec2 o_p_start = vec2(0.,12.);

    float n_numofdigits = float(f_n_numofdigits(float(n)));

    vec2 o = o_trn_fc_nor * vec2(n_numofdigits, 1.);

    float n_idx_digit = floor(o_trn_fc_nor.x / (1. / n_numofdigits));

    int n_digit = f_n_digit(int(n), int(n_idx_digit));

    return f_o_col_char(fract(o), o_p_start+vec2(float(n_digit), 0.));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 o_tres  = vec2(16,16);//target resolution
    vec2 o_scl_tres = o_tres / iResolution.xy;
    vec2 o_ires = iResolution.xy * o_scl_tres;
    vec2 o_fc = fragCoord.xy * o_scl_tres.xy;

    float n_idx_fc = (floor(o_fc.x) + floor(o_fc.y)*floor(o_tres.x));// index
    float n_idx_fc_nor = n_idx_fc / floor(o_tres.x*o_tres.y);

    float n_ratio_1to_iresx = 1./ o_ires.x;//we can make a lowres AA
    float n_ratio_1to_iresolutionx = 1./ iResolution.x;//we need the real resolution for AA
    //needed for anti aliasing ?

    vec2 o_trn_fc_nor = o_fc.xy / o_ires.xy;
    vec2 o_trn_mo_nor = iMouse.xy / iResolution.xy;

    float n_ratio_x_to_y = iResolution.x / iResolution.y; 

    vec2 o_trn_fc_nor_offset = (o_trn_fc_nor - vec2(0.5))*vec2(n_ratio_x_to_y, 1.);
    vec2 o_trn_mo_nor_offset = (o_trn_mo_nor - vec2(0.5))*vec2(n_ratio_x_to_y, 1.);

    vec2 o_fcfract = fract(o_fc);
    float n_dist_border_x = abs(o_fcfract.x-0.5);
    float n_dist_border_y = abs(o_fcfract.y-0.5);
    float n_dist_border = max(n_dist_border_x,n_dist_border_y);
    float n_size = 0.5 - (1./o_tres.x)*0.5;
    float n_aa = n_ratio_1to_iresolutionx*20.;
    n_dist_border = smoothstep(n_size, n_size+n_aa, n_dist_border);


    vec4 o_col = texture(iChannel0, o_fc);

    o_col = f_o_col_num(fract(o_fc), int(n_idx_fc));

    o_col = o_col.xxxx;
    o_col += n_dist_border;

    float b_oddf = float(mod((n_idx_fc),2.) == 0.);
    float b_oddt = 1.-b_oddf;
    float n_invf = 1.*n_idx_fc_nor;
    float n_invt = 1.- n_invf;
    o_col = 
        o_col * vec4(n_invf*b_oddf+n_invt*b_oddt, 0.5, n_invf*b_oddt+n_invt*b_oddf ,  1.);

    fragColor = vec4(o_col);
}
